'use strict';

const _ = require('lodash');
const validator = require('validator');

const db = require('../database');
const user = require('../user');
const posts = require('../posts');
const meta = require('../meta');
const nconf = require('nconf');
const plugins = require('../plugins');
const utils = require('../../public/src/utils');

module.exports = function (Topics) {
	Topics.onNewPostMade = async function (postData) {
		await Promise.all([
			Topics.updateLastPostTime(postData.tid, postData.timestamp),
			Topics.addPostToTopic(postData.tid, postData),
			Topics.syncBacklinks(postData),
		]);
	};

	Topics.syncBacklinks = async function (postData) {
		if (!postData || typeof postData !== 'object' ||
			!isPositiveInteger(postData.pid) || !isNonNegativeInteger(postData.uid) ||
			!isPositiveInteger(postData.tid) || typeof postData.content !== 'string') {
			throw new Error('[[error:invalid-data]]');
		}

		const pid = String(postData.pid);
		const tid = String(postData.tid);
		const backlinkSet = `pid:${pid}:backlinks`;
		const referencedTids = getReferencedTids(postData.content)
			.filter(referencedTid => referencedTid !== tid);
		const existingTids = await db.getSortedSetRange(backlinkSet, 0, -1);
		const existingSet = new Set(existingTids.map(String));
		let validReferencedTids = [];
		if (referencedTids.length) {
			const exists = await Topics.exists(referencedTids);
			validReferencedTids = referencedTids.filter((referencedTid, index) => exists[index]);
		}

		const currentSet = new Set(validReferencedTids);
		const removedTids = existingTids.filter(referencedTid => !currentSet.has(String(referencedTid)));
		const addedTids = validReferencedTids.filter(referencedTid => !existingSet.has(referencedTid));

		for (const referencedTid of removedTids) {
			await removeBacklinkEvent(referencedTid, pid);
		}
		if (removedTids.length) {
			await db.sortedSetRemove(backlinkSet, removedTids);
		}

		const now = Date.now();
		for (const referencedTid of addedTids) {
			await Topics.events.log(referencedTid, {
				type: 'backlink',
				pid: pid,
				href: `/post/${pid}`,
				uid: postData.uid,
			});
		}
		if (addedTids.length) {
			await db.sortedSetAdd(backlinkSet, now, addedTids);
		}

		return addedTids.length + removedTids.length;
	};

	async function removeBacklinkEvent(tid, pid) {
		const eventIds = await db.getSortedSetRange(`topic:${tid}:events`, 0, -1);
		if (!eventIds.length) {
			return;
		}
		const events = await db.getObjects(eventIds.map(eventId => `topicEvent:${eventId}`));
		const matchingEventIds = eventIds.filter((eventId, index) => {
			const event = events[index];
			return event && event.type === 'backlink' && String(event.pid) === pid;
		});
		if (matchingEventIds.length) {
			await Topics.events.purge(tid, matchingEventIds);
		}
	}

	function getReferencedTids(content) {
		const baseUrl = String(nconf.get('url') || '')
			.replace(/\/+$/, '')
			.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		const siteUrl = baseUrl ? `(?:${baseUrl})?` : '';
		const topicLink = new RegExp(
			`(?:^|[^A-Za-z0-9_./:-])${siteUrl}\\/topic\\/(\\d+)(?![A-Za-z0-9_-])(?:\\/[^\\s"'<>)]*)?`,
			'g'
		);
		const tids = new Set();
		let match = topicLink.exec(content);
		while (match) {
			if (isPositiveInteger(match[1])) {
				tids.add(String(parseInt(match[1], 10)));
			}
			match = topicLink.exec(content);
		}
		return Array.from(tids);
	}

	function isPositiveInteger(value) {
		return Number.isInteger(Number(value)) && Number(value) > 0;
