	Topics.syncBacklinks = async function (postData) {
		if (!postData || typeof postData !== 'object' ||
			!isPositiveInteger(postData.pid) || !isNonNegativeInteger(postData.uid) ||
			!isPositiveInteger(postData.tid) || typeof postData.content !== 'string') {
			throw new Error('[[error:invalid-data]]');
		}

		const pid = String(postData.pid);
		const tid = String(postData.tid);
		const backlinkSet = `pid:${pid}:backlinks`;
		const referencedTids = getReferencedTids(postData.content)
			.filter(referencedTid => referencedTid !== tid);
		const existingTids = await db.getSortedSetRange(backlinkSet, 0, -1);
		const existingSet = new Set(existingTids.map(String));
		let validReferencedTids = [];
		if (referencedTids.length) {
			const exists = await Topics.exists(referencedTids);
			validReferencedTids = referencedTids.filter((referencedTid, index) => exists[index]);
		}

		const currentSet = new Set(validReferencedTids);
		const removedTids = existingTids.filter(referencedTid => !currentSet.has(String(referencedTid)));
		const addedTids = validReferencedTids.filter(referencedTid => !existingSet.has(referencedTid));

		await Promise.all(removedTids.map(referencedTid => removeBacklinkEvent(referencedTid, pid)));
		if (removedTids.length) {
			await db.sortedSetRemove(backlinkSet, removedTids);
		}

		const now = Date.now();
		await Promise.all(addedTids.map(referencedTid => Topics.events.log(referencedTid, {
			type: 'backlink',
			pid: pid,
			href: `/post/${pid}`,
			uid: postData.uid,
		})));
		if (addedTids.length) {
			await db.sortedSetAdd(backlinkSet, now, addedTids);
		}

		return addedTids.length + removedTids.length;
	};

